export default function HoursFooter() {
  return (
    <>
      <section id="horarios" className="section section-hours">
        <div className="container">
          <span className="label">¿Cuándo atendemos?</span>
          <h2>Horarios de Atención</h2>
          <p className="hours-days">Jueves a Domingo</p>
          <p className="hours-time">18:00 - 22:30 hrs</p>
          <p className="hours-note section-context">
            Hacé tu pedido con anticipación por WhatsApp para asegurar tu masa de la noche.
          </p>
        </div>
      </section>

      <footer className="footer">
        <div className="container footer-inner">
          <p className="logo">CasiPizza</p>
          <address>Guatemala — Pedidos para llevar y a domicilio</address>
          <a
            href="https://tiktok.com"
            target="_blank"
            rel="noopener noreferrer"
            className="footer-tiktok-link"
          >
            Seguinos en TikTok
          </a>
          <p style={{ fontSize: '12px', color: 'var(--color-text-muted)', marginTop: '1rem' }}>
            © {new Date().getFullYear()} CasiPizza. Todos los derechos reservados.
          </p>
        </div>
      </footer>
    </>
  );
}